// Intentional Buggy Flight Simulator
function flightSim(canvasID) {
  const canvas = document.getElementById(canvasID);
  const ctx = canvas.getContext('2d');
  const width = canvas.width = 500;
  const height = canvas.height = 500;

  let pitch = 0, roll = 0, yaw = 0; // Current spatial orientation
  let spd = 0, alt = 0, head = 0; // Current flight state
  let throttle = 0, gear = 1; // Control inputs

  // Intentionally buggy instrument models
  const altBug = Math.random() * 100 | 0; // Random alt bug on startup
  const headingBug = 360 * Math.random() | 0; // Random heading bug on startup
  const powerFluc = Math.random() < 0.5 ? 1 : -1; // Random power fluctuation direction

  function drawHUD() {
    ctx.font = '16px Arial';
    ctx.textBaseline = 'bottom';

    // Buggy instruments
    const alt = spd >= 100 ? alt + altBug : alt; // Alt bug above 100 kts
    const heading = spd > 200 & head % 90 == 0 ? head + headingBug : head; // Heading bug north, east, south, west
    const power = throttle * 100 + Math.sin(spd / 100) * powerFluc; // Power fluctuation during climb

    ctx.fillStyle = '#fff';
    ctx.fillText(`SPeed: ${spd.toFixed(0)} kt`, 10, 30);
    ctx.fillText(`ALtitude: ${alt.toFixed(0)} ft`, 10, 60);
    ctx.fillText(`HeadIng: ${heading.toFixed(0)}°`, 10, 90);
    ctx.fillText(`ThrotTle: ${throttle.toFixed(2)}`, 10, 120);
    ctx.fillText(`Fuel: ${(alt * 0.5).toFixed(0)} gal`, 10, 150);
    ctx.fillText(`Power: ${power < 0 ? 'Bogged' : power.toFixed(0)}%`, 10, 180);
  }

  function updateSimulation(delta) {
    // Buggy instruments update slower than actual flight state
    alt += (spd / 10000 - alt / 10) * delta;
    heading += (spd / 10 - heading / 5) * delta;
    powerFluc += (spd / 100) * delta;

    // Intentional realistic physics
    const g = 9.81;
    const i = 0.01;
    spd += (gear < 2 ? throttle * 0.02 : 0) * delta;  // Throttle based on gear-down/gear-up
    alt += spd * delta;  // Descend on zero throttle
    heading += Math.atan2(roll, (1 + 1 / Math.abs(pitch))) * 0.9 * delta; // Turn based on roll and pitch
    pitch += -yaw * 0.03 * delta; // Intended pitch from yaw

    // Intentional physics bugs
    if (pitch > 30) alt = Math.max(0, alt - 100 * delta); // Unintentional pitch limit and loss of altitude
    if (spd > 400) { spd *= 0.99; alt += -75 * g * delta; } // Bogus high-speed performance loss
    if (gear == 1) { spd = Math.max(0, spd - 10 * delta); alt += 75 * g * delta; } // Bogus gear-related power loss
  }

  function drawTerrain() {
    ctx.fillStyle = `hsl(${50 - (alt / 8000) * 100}deg,30%,50%)`;
    ctx.fillRect(0, height / 2, width, height);

    ctx.fillStyle = `hsl(${50 - (alt / 3000) | 0}deg,20%,40%)`;
    ctx.fillRect(0, height / 2, width, height / 2);
  }

  function draw Cockpit() {
    // Slightly misaligned gauges for intentional datameter bugs
    ctx.fillStyle = 'tan';
    ctx.fillRect(0, 0, 500, 100);

    ctx.save();
    ctx.translate(200, 50);
    ctx.rotate(-pitch - yaw * 2);
    drawTerrain();
    ctx.restore();

    ctx.save();
    ctx.translate(180, 120);
    ctx.rotate(-yaw);
    ctx.fillStyle = 'cornflowerblue';
    ctx.fillRect(0, 0, 40, -10);
    ctx.fillStyle = '#000';
    if (pitch > 45 || alt > 50000) ctx.fillStyle = 'red';
    ctx.strokeStyle = '#666';
    ctx.lineWidth = 3;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.beginPath();
    ctx.arc(0, 0, 30, 0, Math.PI * 2);
    ctx.stroke();
    ctx.fillStyle = '#666';
    ctx.fill();
    ctx.clip();
    ctx.gradient = ctx.createLinearGradient(0, 0, 0, 30);
    ctx.gradient.addColorStop(0, '#fff');
    ctx.gradient.addColorStop(1, 'lightyellow');
    ctx.fillStyle = ctx.gradient;
    ctx.fillRect(0, 0, 30, -30);
    drawHUD();
  }

  function animate(timestamp) {
    const delta = timestamp - lastTime;
    updateSimulation(delta);
    drawCockpit();
    lastTime = timestamp;
    requestAnimationFrame(animate);
  }
  const lastTime = performance.now();
  animate(lastTime);
}

flightSim('flight-simulator')
